INSERT INTO "public"."submissions" ("id", "created_at", "user_name", "user_email", "user_phone", "is_whatsapp", "status", "answers") VALUES ('a82b11b6-76a7-4b5b-9eac-835dc2a1eb89', '2026-01-21 20:34:21.705704+00', 'Willian José de Souza Marçal ', 'williantog295@gmail.com', '(11) 9.7756-0264', 'true', 'Iniciado', '{"userRoles":"Alunos de educação física ","designGoal":"portfolio","hasPayment":"yes","keyFeatures":"Cadastro de alunos, plataforma de ensino, relatórios de vendas...","projectGoal":"Este site foi criado com o objetivo de apresentar, de forma clara e transparente, a maneira como eu entendo e aplico o treinamento físico. Aqui você vai encontrar um pouco do meu método de trabalho, da minha trajetória como treinador e atleta, além de resultados construídos ao longo do tempo com alunos reais e processos consistentes.\\nA ideia não é vender promessas rápidas ou atalhos irreais, mas mostrar como o treinamento bem planejado, individualizado e feito com constância gera evolução de verdade. Cada conteúdo apresentado aqui reflete a minha experiência prática, minha vivência no esporte e a forma responsável com que conduzo o treinamento.\\nEste espaço também serve para informar, orientar e aproximar pessoas que buscam saúde, desempenho e evolução física de maneira consciente. Se você acredita em processo, disciplina e resultado construído passo a passo, este site é para você.","projectName":"Educador Físico ","designColors":"elegant","platformType":"web","designDensity":"clean","designExample":"dark","designElements":"photos","designSensation":"light","paymentProvider":"Mercado pago","designPersonality":"friendly","niceToHaveFeatures":"Integração com redes sociais "}'), ('fd6dc8fa-abb5-414e-9ae8-701211979ce4', '2026-01-21 12:50:28.896486+00', 'LEANDRO HENRIQUE DE SOUZA', 'LEANDROSOUZA50@HOTMAIL.COM', '(31) 9.9515-9348', 'true', 'Necessário Ajustes', '{"userRoles":"MARCAMOS UMA REUNIAO","designGoal":"utility","hasPayment":"yes","keyFeatures":"RESOLVER EM REUNIAO","projectGoal":"NÃO SERÁ UM SOFTWARE E SIM UMA PROPOSTA DE VENDAS. TALVEZ NA SUA VISÃO PODE ENTRAR UM SISTEMA DE AUTOMAÇÃO PARA FACILITAR.","projectName":"TESTE MAS QUERO FALAR COM VOCE DEPOIS SOBRE UM PROJETO DE VENDAS...","designColors":"elegant","platformType":"both","designDensity":"dense","designExample":"sober","designElements":"none","designSensation":"professional","paymentProvider":"MERCADO PAGO","designPersonality":"functional","niceToHaveFeatures":"MULTI-PLATAFORMA (VARIAS PESSOAS PODEREM ENTRAR AO MESMO TEMPO COM LOGIN DIFERENTE"}');